// The testbed's single-page app (bn-1lww): one self-contained script, no
// framework, no build step, no external resource. Served as the "bundle" of
// the shell page by crates/teapot-testbed/src/endpoints/app/spa.rs.
//
// What it is for: its API paths appear nowhere a crawl that does not run
// JavaScript can read them. No path of the API is written out in this file or
// in the HTML. The base of the API and the name of each call come from a
// config document fetched at run time (words written backwards), and this
// script puts them together, the way a bundler's output hides them from a
// literal scan. A crawl that runs the page (a browser) makes the calls; a
// crawl that reads text does not find them.
(function () {
  'use strict';

  var root = document.getElementById('root');
  var view = null;
  var cfg = null;
  var cfgWait = null;
  var epoch = 0;
  var timer = null;
  var shown = null;

  function rev(s) {
    return s.split('').reverse().join('');
  }

  function esc(s) {
    var map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
    return String(s).replace(/[&<>"']/g, function (c) {
      return map[c];
    });
  }

  function path(words) {
    return '/' + words.join('/');
  }

  function pageUrl(rest) {
    return path(['app', 'spa'].concat(rest || []));
  }

  function byId(id) {
    return document.getElementById(id);
  }

  // The config document: where the API lives and what its calls are called.
  function loadConfig() {
    if (cfg) {
      return Promise.resolve(cfg);
    }
    if (!cfgWait) {
      cfgWait = fetch(path(['app', 'api', 'spa', 'config']), { credentials: 'same-origin' })
        .then(function (r) {
          if (!r.ok) {
            throw new Error('config ' + r.status);
          }
          return r.json();
        })
        .then(function (j) {
          cfg = j;
          return j;
        })
        .catch(function (e) {
          cfgWait = null;
          throw e;
        });
    }
    return cfgWait;
  }

  function apiUrl(name, tail, query) {
    var words = cfg.pre.map(rev).reverse();
    words.push(rev(cfg.seg[name]));
    if (tail) {
      words.push(encodeURIComponent(tail));
    }
    return path(words) + (query || '');
  }

  // One API call: { status, body }.
  function call(name, o) {
    o = o || {};
    return loadConfig()
      .then(function () {
        return fetch(apiUrl(name, o.tail, o.query), {
          method: o.method || 'GET',
          credentials: 'same-origin',
          headers: o.headers || {},
          body: o.body
        });
      })
      .then(function (r) {
        return r.json().then(function (j) {
          return { status: r.status, body: j };
        });
      });
  }

  // A state-changing call: a fresh CSRF token first, sent in the header.
  function post(name, body) {
    return fetch(path(['app', 'api', 'csrf']), { credentials: 'same-origin' })
      .then(function (r) {
        return r.json();
      })
      .then(function (t) {
        if (!t.csrf_token) {
          return { status: 401, body: t };
        }
        return call(name, {
          method: 'POST',
          headers: {
            'X-CSRF-Token': t.csrf_token,
            'Content-Type': 'application/x-www-form-urlencoded'
          },
          body: body
        });
      });
  }

  // True when the answer is a success; otherwise says why in the view.
  function good(res, my) {
    if (my !== undefined && my !== epoch) {
      return false;
    }
    if (res.status === 200) {
      return true;
    }
    if (res.status === 401) {
      view.innerHTML = '<p id="signed-out" class="error">You are signed out.</p>';
    } else {
      view.innerHTML = '<p id="call-failed" class="error">The request failed (' + res.status + ').</p>';
    }
    return false;
  }

  function link(id, href, text, local) {
    return '<a id="' + id + '" href="' + esc(href) + '"' + (local ? ' data-spa="1"' : '') + '>' + esc(text) + '</a>';
  }

  function home(my) {
    view.innerHTML =
      '<h2 id="home-title">Items</h2><ul id="items"><li>Loading</li></ul>' +
      '<div id="tabs" role="tablist">' +
      '<button id="tab-overview" role="tab" aria-selected="true">Overview</button> ' +
      '<button id="tab-summary" role="tab" aria-selected="false">Summary</button></div>' +
      '<div id="tabpanel">Overview: five items. The Summary tab asks the server.</div>' +
      '<p><button id="btn-tips">Show tips</button></p>' +
      '<p id="tips" hidden>Tips appear without any request.</p>' +
      '<p><button id="btn-delete">Delete account</button></p><p id="delete-result"></p>';
    var panel = byId('tabpanel');
    byId('tab-overview').addEventListener('click', function () {
      byId('tab-overview').setAttribute('aria-selected', 'true');
      byId('tab-summary').setAttribute('aria-selected', 'false');
      panel.textContent = 'Overview: five items. The Summary tab asks the server.';
    });
    byId('tab-summary').addEventListener('click', function () {
      byId('tab-overview').setAttribute('aria-selected', 'false');
      byId('tab-summary').setAttribute('aria-selected', 'true');
      call('summary').then(function (res) {
        if (res.status === 200) {
          panel.textContent = 'Summary: ' + res.body.items + ' items, asked ' + res.body.asked + ' times.';
        } else {
          panel.textContent = 'Summary unavailable (' + res.status + ').';
        }
      });
    });
    byId('btn-tips').addEventListener('click', function () {
      var tips = byId('tips');
      tips.hidden = !tips.hidden;
    });
    byId('btn-delete').addEventListener('click', function () {
      post('erase', '').then(function (res) {
        byId('delete-result').textContent = res.status === 200 ? 'Account deleted (simulated).' : 'Not deleted (' + res.status + ').';
      });
    });
    call('items').then(function (res) {
      if (!good(res, my)) {
        return;
      }
      byId('items').innerHTML = res.body.items
        .map(function (it) {
          return '<li>' + link('item-link-' + it.id, pageUrl(['items', String(it.id)]), it.name, true) + '</li>';
        })
        .join('');
    });
  }

  function item(my, id) {
    view.innerHTML =
      '<h2 id="item-title">Loading</h2><p id="item-price"></p>' +
      '<p>' + link('item-back', pageUrl(), 'All items', true) + '</p>';
    call('items', { tail: id || '' }).then(function (res) {
      if (my !== epoch) {
        return;
      }
      if (res.status === 404) {
        byId('item-title').textContent = 'No such item';
        return;
      }
      if (!good(res, my)) {
        return;
      }
      byId('item-title').textContent = res.body.name;
      byId('item-price').textContent = 'Price: ' + (res.body.price_cents / 100).toFixed(2);
    });
  }

  function forms() {
    view.innerHTML =
      '<h2 id="forms-title">Forms</h2>' +
      '<form id="form-search" method="get" action="' + pageUrl(['search']) + '">' +
      '<label>Search <input id="search-q" name="q" type="text"></label> ' +
      '<button id="search-go" type="submit">Search</button></form>' +
      '<form id="form-feedback" method="post" action="' + pageUrl(['feedback']) + '">' +
      '<label>Message <input id="fb-message" name="message" type="text"></label> ' +
      '<button id="fb-send" type="submit">Send feedback</button></form>' +
      '<p id="fb-result"></p>';
    byId('form-feedback').addEventListener('submit', function (e) {
      e.preventDefault();
      var text = byId('fb-message').value;
      post('feedback', 'message=' + encodeURIComponent(text)).then(function (res) {
        byId('fb-result').textContent = res.status === 200 ? 'Thanks: ' + res.body.length + ' characters received.' : 'Not sent (' + res.status + ').';
      });
    });
  }

  function search(my) {
    var q = new URLSearchParams(location.search).get('q') || '';
    view.innerHTML =
      '<h2 id="search-title">Search results</h2><p id="search-query"></p><ul id="results"></ul>' +
      '<p>' + link('search-back', pageUrl(['forms']), 'Back to the forms', true) + '</p>';
    byId('search-query').textContent = 'You searched for: ' + q;
    call('lookup', { query: '?q=' + encodeURIComponent(q) }).then(function (res) {
      if (!good(res, my)) {
        return;
      }
      byId('results').innerHTML = res.body.results
        .map(function (it) {
          return '<li>' + esc(it.name) + '</li>';
        })
        .join('');
    });
  }

  // A view that never goes network-quiet: it asks the server again 300 ms
  // after each answer, until the route changes.
  function live(my) {
    view.innerHTML = '<h2 id="live-title">Live</h2><p id="tick">waiting</p>';
    function again() {
      call('pulse').then(function (res) {
        if (!good(res, my)) {
          return;
        }
        byId('tick').textContent = 'tick ' + res.body.tick;
        timer = setTimeout(again, 300);
      });
    }
    again();
  }

  // The one request to another origin, made when this view loads.
  function partners(my) {
    view.innerHTML = '<h2 id="partners-title">Partners</h2><p id="partners-status">Contacting the partner</p>';
    loadConfig().then(function (c) {
      if (my !== epoch) {
        return;
      }
      if (!c.off) {
        byId('partners-status').textContent = 'No partner is configured.';
        return;
      }
      fetch(c.off + path(['app', 'api', 'spa', 'hello']), { mode: 'no-cors' }).then(
        function () {
          byId('partners-status').textContent = 'The partner answered.';
        },
        function () {
          byId('partners-status').textContent = 'The partner could not be reached.';
        }
      );
    });
  }

  function help() {
    view.innerHTML = '<h2 id="help-title">Help</h2><p>This view is a hash route: no request is made.</p>';
  }

  function missing() {
    view.innerHTML = '<p id="not-found">No such view.</p>';
  }

  function render() {
    // A hash change fires both events: draw the same address once.
    if (shown === location.href) {
      return;
    }
    shown = location.href;
    epoch += 1;
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    var my = epoch;
    if (location.hash === '#/help') {
      help();
      return;
    }
    var rest = location.pathname.split('/').filter(Boolean).slice(2);
    switch (rest[0]) {
      case undefined:
        home(my);
        break;
      case 'items':
        if (rest[1]) {
          item(my, rest[1]);
        } else {
          missing();
        }
        break;
      case 'forms':
        forms();
        break;
      case 'search':
        search(my);
        break;
      case 'live':
        live(my);
        break;
      case 'partners':
        partners(my);
        break;
      default:
        missing();
    }
  }

  function go(href) {
    history.pushState({}, '', href);
    render();
  }

  root.innerHTML =
    '<h1 id="app-title">Testbed single-page app</h1>' +
    '<nav id="nav">' +
    link('nav-home', pageUrl(), 'Home', true) + ' ' +
    link('nav-forms', pageUrl(['forms']), 'Forms', true) + ' ' +
    link('nav-live', pageUrl(['live']), 'Live', true) + ' ' +
    link('nav-partners', pageUrl(['partners']), 'Partners', true) + ' ' +
    link('nav-help', '#/help', 'Help', false) +
    '</nav><main id="view"></main>';
  view = byId('view');

  root.addEventListener('click', function (e) {
    var a = e.target.closest ? e.target.closest('a[data-spa]') : null;
    if (!a || e.defaultPrevented || e.button !== 0 || e.ctrlKey || e.metaKey || e.shiftKey || e.altKey) {
      return;
    }
    e.preventDefault();
    go(a.getAttribute('href'));
  });
  window.addEventListener('popstate', render);
  window.addEventListener('hashchange', render);
  render();
})();

